import java.util.*;

public class Solution {
    record Aresta(int para, int peso) {}

    static int[] shortestPaths(int n, int[][] edges, int source) {
        if (source < 0 || source >= n) throw new IllegalArgumentException("origem invalida");
        var adj = new ArrayList<List<Aresta>>(n);
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (var e : edges) adj.get(e[0]).add(new Aresta(e[1], e[2]));

        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[source] = 0;

        var fila = new PriorityQueue<int[]>(Comparator.comparingInt(a -> a[0]));
        fila.add(new int[]{0, source});

        while (!fila.isEmpty()) {
            var atual = fila.poll();
            int d = atual[0], u = atual[1];
            if (d > dist[u]) continue;
            for (var a : adj.get(u)) {
                int nd = d + a.peso();
                if (nd < dist[a.para()]) {
                    dist[a.para()] = nd;
                    fila.add(new int[]{nd, a.para()});
                }
            }
        }
        return dist;
    }
}

