import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void caminhosMinimos() {
        int[] d = Solution.shortestPaths(4,
            new int[][]{{0,1,1},{1,2,2},{0,2,5},{2,3,1}}, 0);
        assertArrayEquals(new int[]{0,1,3,4}, d);
    }

    @Test void inalcancavel() {
        int[] d = Solution.shortestPaths(3, new int[][]{{0,1,2}}, 0);
        assertEquals(Integer.MAX_VALUE, d[2]);
    }

    @Test void escolheArestaMaisBarata() {
        int[] d = Solution.shortestPaths(2,
            new int[][]{{0,1,10},{0,1,3}}, 0);
        assertEquals(3, d[1]);
    }

    @Test void origemInvalida() {
        assertThrows(IllegalArgumentException.class,
            () -> Solution.shortestPaths(2, new int[][]{}, 5));
    }
}
